const state = { upload: null, result: null, processId: sessionStorage.getItem('deliveryiq-process-id'), templateType: 'simple', config: { statusCategories: ['Delivered', 'In Transit', 'NDR', 'RTO', 'Cancelled', 'Other'], masterCategories: [], productCategories: [] }, reportId: null, universal: { page: 1, limit: 25, controller: null, detailCache: new Map(), loading: false } };
const $ = (selector) => document.querySelector(selector);
function el(tag, text, className) { const node = document.createElement(tag); if (text !== undefined) node.textContent = text; if (className) node.className = className; return node; }
function clear(node) { node.replaceChildren(); }
function page(name) { if (typeof closeMobileMenu === 'function') closeMobileMenu(); document.querySelectorAll('[data-page-panel]').forEach((node) => { node.hidden = node.dataset.pagePanel !== name; }); document.querySelectorAll('[data-page]').forEach((node) => node.classList.toggle('is-active', node.dataset.page === name)); if (name === 'reports' || name === 'history') loadReports(); if (name === 'universal') loadUniversal(); if (name === 'products') loadProducts(); if (name === 'statuses') loadStatuses(); }
function setUpload(title, text) { $('#upload-state-title').textContent = title; $('#upload-state-copy').textContent = text; }
