function renderReview() { const result = state.result; const statuses = result.classifications.statuses; const products = result.classifications.products; const unresolvedStatuses = statuses.filter((item) => item.classificationRequired); const unresolvedProducts = products.filter((item) => item.classificationRequired); const unresolved = unresolvedStatuses.length + unresolvedProducts.length; const known = products.filter((item) => item.mappingSource === 'known').length; const suggested = products.filter((item) => item.suggestedCategory).length; const resolved = products.length + statuses.length - unresolved; const selectedProducts = new Set(); const target = notice('Report Review', `${products.length} unique products · ${resolved} resolved · ${unresolved} remaining. ${unresolved ? `${unresolved} products still need your attention.` : 'All classifications are resolved.'}`); const progress = el('div', undefined, 'classification-summary'); progress.append(el('span', `Total unique products: ${products.length}`, 'summary-ok'), el('span', `Known products: ${known}`, 'summary-ok'), el('span', `AI suggestions: ${suggested}`), el('span', `Approved/resolved: ${resolved}`, 'summary-ok'), el('span', `Remaining: ${unresolved}`, unresolved ? 'summary-warning' : 'summary-ok')); target.append(progress); if (result.classifications.productProviderUnavailable) target.append(el('p', 'AI could not classify one or more products. Please assign a category manually; known products can still continue.', 'summary-warning'));
  if (unresolvedStatuses.length) { const statusList = el('div', undefined, 'mapping-cards'); statusList.append(el('h3', 'Statuses requiring review')); unresolvedStatuses.forEach((item) => statusList.append(reviewItem(item, 'status'))); target.append(statusList); }
  if (result.classifications.productProviderError) target.append(el('p', result.classifications.productProviderError, 'summary-warning')); const productList = el('div', undefined, 'mapping-cards'); productList.append(el('h3', 'Products'));
  if (unresolvedProducts.length) { const toolbar = el('div', undefined, 'review-actions'); const approveAll = el('button', `Approve All & Save (${suggested})`, 'button button-primary'); approveAll.type = 'button'; approveAll.addEventListener('click', async () => { const ready = unresolvedProducts.filter((item) => item.suggestedCategory); const failures = []; for (const item of ready) try { await saveProductDecision(item, item.suggestedMasterCategory, item.suggestedProductCategory, 'AI Approved'); } catch (error) { failures.push(`${item.value}: ${error.message}`); } await refreshConfig(); renderReview(); if (failures.length) notice('Some AI approvals could not be saved', failures.join(' '), true); }); toolbar.append(approveAll); productList.append(toolbar); } products.forEach((item) => productList.append(reviewItem(item, 'product', selectedProducts)));
  target.append(productList); const generate = el('button', 'Generate report', 'button button-primary'); generate.type = 'button'; generate.disabled = Boolean(unresolved); generate.addEventListener('click', generateReport); target.append(generate); const remove = el('button', 'Remove Report', 'button button-secondary'); remove.type = 'button'; remove.addEventListener('click', async () => { if (!confirm('Remove this report process? Your unfinished review will be discarded. Saved product mappings will not be deleted.')) return; const response = await fetch(`/api/report-processes/${encodeURIComponent(state.processId)}`, { method: 'DELETE' }); if (!response.ok) return notice('Report could not be removed', 'Please try again.', true); sessionStorage.removeItem('deliveryiq-process-id'); state.processId = null; state.result = null; setUploadLocked(null); notice('Report process removed', 'Your unfinished review was discarded. Saved product mappings were not deleted.'); }); target.append(remove); }
